INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 2175, 'អាជីវករម្នាក់ចំណាយ \(175\,000\) ៛ ទិញដំឡូងបារាំង \(30\) kg និងត្រសក់ \(20\) kg ដែលមានតម្លៃស្មើគ្នាក្នុងមួយ kg។ គាត់លក់ដំឡូងចំណេញ \(500\) ៛/kg ប៉ុន្តែលក់ត្រសក់ខាត \(300\) ៛/kg។ គាត់ចំណេញឬខាតសរុបប៉ុន្មាន?', NULL, '[]', 0, NULL, 5, 'writing', 'ដំឡូងបារាំង ចំណេញ \(30 \times 500 = 15\,000\) ៛ (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 2176, 'ក្រុមហ៊ុនមួយក្នុងមួយឆ្នាំ ត្រីមាសទី ១ ខាត \(50\,000\) ទី ២ ខាត \(20\,000\) ទី ៣ ចំណេញ \(30\,000\) ទី ៤ ចំណេញ \(65\,000\) (ម៉ឺនរៀល)។ ក. គណនាលទ្ធផលសរុបប្រចាំឆ្នាំ។ ខ. គណនាលទ្ធផលមធ្យមក្នុងមួយត្រីមាស។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(-50\,000 - 20\,000 + 30\,000 + 65\,000 = 25\,000\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 2177, 'តារាងប្រាក់ខាត (ចំនួនអវិជ្ជមាន) និងចំណេញ (ចំនួនវិជ្ជមាន) គិតជាម៉ឺនរៀល ក្នុងមួយសប្តាហ៍ ៖ ចន្ទ \(-4\) អង្គារ \(2\) ពុធ \(3\) ព្រហស្បតិ៍ \(-2\) សុក្រ \(-3\) សៅរ៍ \(5\) អាទិត្យ \(7\)។ ក. រកលទ្ធផលសរុប។ ខ. ថ្ងៃណាចំណេញច្រើនជាងគេ? ថ្ងៃណាខាតច្រើនជាងគេ?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(-4 + 2 + 3 - 2 - 3 + 5 + 7 = 8\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 2178, 'ទូកមួយធ្វើដំណើរលើទន្លេ ចម្ងាយរាប់ពីកំពង់ផែ \(O\) (ទិសទៅខាងលើទន្លេតំណាងដោយចំនួនវិជ្ជមាន)។ ទូកចេញពី \(O\) ទៅ \(+12\) km រួចត្រឡប់ \(20\) km ទៅទិសផ្ទុយ រួចទៅមុខ \(5\) km។ ក. ទីតាំងចុងក្រោយនៅត្រង់ណា? ខ. ចម្ងាយសរុបដែលទូកបានធ្វើដំណើរ? គ. ទូកនៅឆ្ងាយពី \(O\) ប៉ុន្មាន km?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(12 - 20 + 5 = -3\) ដូច្នេះនៅ \(-3\) km (2 ពិន្ទុ)
